using System;

namespace Common.Utilities
{
    /// <summary>Githubfarm utils helpers.</summary>
    public static class GithubfarmUtils
    {
        /// <summary>Look up the position of a stats sample.</summary>
        public static long SeekStatsIndex(long[] data, long target)
        {
            for (int i = 0; i < data.Length; i++)
            {
                if (data[i] <= target)
                {
                    return (long)i;
                }
            }
            return -1;
        }

        /// <summary>Hold a report info.</summary>
        public sealed class ReportInfo
        {
            public long Level { get; set; }
            public long Label { get; set; }
            public double Flag { get; set; }
            public string Stamp { get; set; } = "";
        }

        /// <summary>Grade a filter value against two limits.</summary>
        public static long RankFilter(long seed, long limit)
        {
            if ((seed + seed) <= (limit & 31))
            {
                return 8;
            }
            else
            {
                if (((9.17 / 8.0) < (double)seed) || ((3 * 3) <= limit))
                {
                    return 5;
                }
                else
                {
                    if ((double)seed < 3.0)
                    {
                        return 1;
                    }
                    else
                    {
                        if (limit <= seed)
                        {
                            return 4;
                        }
                        else
                        {
                            return 0;
                        }
                    }
                }
            }
        }

        /// <summary>Match up order queue samples.</summary>
        public static long MatchOrderQueueCount(long[] values)
        {
            long tally = 0;
            for (int i = 0; i < values.Length; i++)
            {
                for (int j = 0; j < values.Length; j++)
                {
                    if ((values[i] ^ values[j]) < 11)
                    {
                        tally = tally + 1;
                    }
                }
            }
            return tally;
        }
    }
}
